{
  "promos": [
    {
      "title": "You Were Always Meant to Kneel",
      "start_block": "B006",
      "end_block": "B044",
      "hook": "Catherine in an ornate violet gown looms over a chained Juliana and sneers, \"Look at you. The great Lady Juliana Ashcroft.\"",
      "cliffhanger": "Juliana, still in chains, declares her husband has \"more honor than the people sitting above this dungeon\" as Catherine holds the smoldering iron between them.",
      "why": "Opens on a cruel power imbalance and builds through escalating verbal duels to a defiant moral victory that leaves the physical threat unresolved.",
      "context_gap": "A stranger may not know Alexander is the scarred soldier she married or that Catherine poisoned the Duchess."
    },
    {
      "title": "Then Why Do You Need Me to Bow",
      "start_block": "B045",
      "end_block": "B071",
      "hook": "Catherine holds the smoldering iron between them and mocks, \"You call that marriage?\" while Juliana answers with pure conviction, \"I call it love.\"",
      "cliffhanger": "Catherine's aristocratic facade shatters as she screams \"Enough!\" after Juliana asks why she is so desperate to make her kneel.",
      "why": "A tight psychological duel that escalates from mockery to a piercing accusation, ending exactly as Catherine loses control and violence becomes imminent.",
      "context_gap": "A stranger may not know the full history of Gerald abandoning Juliana or that Catherine is behind the poisoning frame-up."
    },
    {
      "title": "Your Mother's Life's Work Becomes Ash",
      "start_block": "B072",
      "end_block": "B087",
      "hook": "A red-hot poker presses into the delicate pages of Juliana's mother's botanical book as parchment hisses and blackens under extreme heat.",
      "cliffhanger": "The glowing orange iron tip stops inches from Juliana's trembling eye, its ember reflected in her pupil as she gasps in raw terror.",
      "why": "The episode's most visceral moment: destruction of a treasured heirloom followed by a direct threat of disfigurement, cut before any outcome.",
      "context_gap": "A stranger may not know the book is Juliana's late mother's herbarium or that Catherine is using it to frame her for witchcraft."
    }
  ],
  "moments": [
    {
      "start_block": "B006",
      "end_block": "B011",
      "kind": "hook",
      "description": "Catherine enters the dungeon in an ornate gown and taunts a chained Juliana, calling her a common criminal."
    },
    {
      "start_block": "B023",
      "end_block": "B036",
      "kind": "emotional",
      "description": "Juliana fires back that Gerald chose money, Clarissa chose a coward, and she chose herself, refusing to break."
    },
    {
      "start_block": "B047",
      "end_block": "B052",
      "kind": "reveal",
      "description": "Juliana declares her marriage to the scarred soldier is love and that she can still look Catherine in the eyes."
    },
    {
      "start_block": "B085",
      "end_block": "B087",
      "kind": "cliffhanger",
      "description": "Catherine swings the glowing branding iron toward Juliana's face, stopping inches from her eye as she recoils in terror."
    }
  ]
}
